41	/**
42	 * Hoodie data source/sink factory.
43	 */
44	public class HoodieTableFactory implements TableSourceFactory<RowData>, TableSinkFactory<RowData> {
45	  public static final String FACTORY_ID = "hudi";
46	
47	  @Override
48	  public TableSource<RowData> createTableSource(TableSourceFactory.Context context) {
49	    Configuration conf = FlinkOptions.fromMap(context.getTable().getOptions());
50	    conf.setString(FlinkOptions.TABLE_NAME.key(), context.getObjectIdentifier().getObjectName());
51	    conf.setString(FlinkOptions.PARTITION_PATH_FIELD, String.join(",", context.getTable().getPartitionKeys()));
52	    Path path = new Path(conf.getOptional(FlinkOptions.PATH).orElseThrow(() ->
53	        new ValidationException("Option [path] should be not empty.")));
54	    return new HoodieTableSource(
55	        TableSchemaUtils.getPhysicalSchema(context.getTable().getSchema()),
56	        path,
57	        context.getTable().getPartitionKeys(),
58	        conf.getString(FlinkOptions.PARTITION_DEFAULT_NAME),
59	        conf);
60	  }
61	
62	  @Override
63	  public TableSink<RowData> createTableSink(TableSinkFactory.Context context) {
64	    Configuration conf = FlinkOptions.fromMap(context.getTable().getOptions());
65	    conf.setString(FlinkOptions.TABLE_NAME.key(), context.getObjectIdentifier().getObjectName());
66	    conf.setString(FlinkOptions.PARTITION_PATH_FIELD, String.join(",", context.getTable().getPartitionKeys()));
67	    return new HoodieTableSink(conf,
68	        TableSchemaUtils.getPhysicalSchema(context.getTable().getSchema()),
69	        context.isBounded());
70	  }
71	
72	  @Override
73	  public Map<String, String> requiredContext() {
74	    Map<String, String> context = new HashMap<>();
75	    context.put(FactoryUtil.CONNECTOR.key(), FACTORY_ID);
76	    return context;
77	  }
78	
79	  @Override
80	  public List<String> supportedProperties() {
81	    // contains format properties.
82	    return Collections.singletonList("*");
83	  }
84	}
