62	  public static DataType convertToDataType(Schema schema) {
63	    switch (schema.getType()) {
64	      case RECORD:
65	        final List<Schema.Field> schemaFields = schema.getFields();
66	
67	        final DataTypes.Field[] fields = new DataTypes.Field[schemaFields.size()];
68	        for (int i = 0; i < schemaFields.size(); i++) {
69	          final Schema.Field field = schemaFields.get(i);
70	          fields[i] = DataTypes.FIELD(field.name(), convertToDataType(field.schema()));
71	        }
72	        return DataTypes.ROW(fields).notNull();
73	      case ENUM:
74	        return DataTypes.STRING().notNull();
75	      case ARRAY:
76	        return DataTypes.ARRAY(convertToDataType(schema.getElementType())).notNull();
77	      case MAP:
78	        return DataTypes.MAP(
79	            DataTypes.STRING().notNull(),
80	            convertToDataType(schema.getValueType()))
81	            .notNull();
82	      case UNION:
83	        final Schema actualSchema;
84	        final boolean nullable;
85	        if (schema.getTypes().size() == 2
86	            && schema.getTypes().get(0).getType() == Schema.Type.NULL) {
87	          actualSchema = schema.getTypes().get(1);
88	          nullable = true;
89	        } else if (schema.getTypes().size() == 2
90	            && schema.getTypes().get(1).getType() == Schema.Type.NULL) {
91	          actualSchema = schema.getTypes().get(0);
92	          nullable = true;
93	        } else if (schema.getTypes().size() == 1) {
94	          actualSchema = schema.getTypes().get(0);
95	          nullable = false;
96	        } else {
97	          // use Kryo for serialization
98	          return new AtomicDataType(
99	              new TypeInformationRawType<>(false, Types.GENERIC(Object.class)));
100	        }
101	        DataType converted = convertToDataType(actualSchema);
102	        return nullable ? converted.nullable() : converted;
103	      case FIXED:
104	        // logical decimal type
105	        if (schema.getLogicalType() instanceof LogicalTypes.Decimal) {
106	          final LogicalTypes.Decimal decimalType =
107	              (LogicalTypes.Decimal) schema.getLogicalType();
108	          return DataTypes.DECIMAL(decimalType.getPrecision(), decimalType.getScale())
109	              .notNull();
110	        }
111	        // convert fixed size binary data to primitive byte arrays
112	        return DataTypes.VARBINARY(schema.getFixedSize()).notNull();
113	      case STRING:
114	        // convert Avro's Utf8/CharSequence to String
115	        return DataTypes.STRING().notNull();
116	      case BYTES:
117	        // logical decimal type
118	        if (schema.getLogicalType() instanceof LogicalTypes.Decimal) {
119	          final LogicalTypes.Decimal decimalType =
120	              (LogicalTypes.Decimal) schema.getLogicalType();
121	          return DataTypes.DECIMAL(decimalType.getPrecision(), decimalType.getScale())
122	              .notNull();
123	        }
124	        return DataTypes.BYTES().notNull();
125	      case INT:
126	        // logical date and time type
127	        final org.apache.avro.LogicalType logicalType = schema.getLogicalType();
128	        if (logicalType == LogicalTypes.date()) {
129	          return DataTypes.DATE().notNull();
130	        } else if (logicalType == LogicalTypes.timeMillis()) {
131	          return DataTypes.TIME(3).notNull();
132	        }
133	        return DataTypes.INT().notNull();
134	      case LONG:
135	        // logical timestamp type
136	        if (schema.getLogicalType() == LogicalTypes.timestampMillis()) {
137	          return DataTypes.TIMESTAMP(3).notNull();
138	        } else if (schema.getLogicalType() == LogicalTypes.timestampMicros()) {
139	          return DataTypes.TIMESTAMP(6).notNull();
140	        } else if (schema.getLogicalType() == LogicalTypes.timeMillis()) {
141	          return DataTypes.TIME(3).notNull();
142	        } else if (schema.getLogicalType() == LogicalTypes.timeMicros()) {
143	          return DataTypes.TIME(6).notNull();
144	        }
145	        return DataTypes.BIGINT().notNull();
146	      case FLOAT:
147	        return DataTypes.FLOAT().notNull();
148	      case DOUBLE:
149	        return DataTypes.DOUBLE().notNull();
150	      case BOOLEAN:
151	        return DataTypes.BOOLEAN().notNull();
152	      case NULL:
153	        return DataTypes.NULL();
154	      default:
155	        throw new IllegalArgumentException("Unsupported Avro type '" + schema.getType() + "'.");
156	    }
157	  }
